"""One geometry source for native wearable armor, editable Bedrock geometry, and the six-barrel item."""
import json, math
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def write(path,value):
 p=R/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
# x,y,z,w,h,d,material. Native humanoid local coordinates; each limb follows the player.
parts={
'head':[( -5,-9,-5,10,9,10,1),(-5.6,-7,-2,1.3,5,5,2),(4.3,-7,-2,1.3,5,5,2),(-3,-10,-3,6,1,6,0),(-4,-1,-5.5,8,2,1.2,2),(-5,-8,-5.4,10,1,1,3)],
'body':[(-5,0,-3.5,10,12,7,0),(-5.6,.5,-4.2,4,5,1.5,1),(1.6,.5,-4.2,4,5,1.5,1),(-2,1,-4.4,4,6,1.5,2),(-5,7,-4.1,10,2,1,1),(-4,10,-4,8,3,1.5,2),(-4.5,2,3,9,10,5,2),(-5,1,7,3,11,3,0),(2,1,7,3,11,3,0),(-5.4,0,5.5,3.8,2,5,3),(1.6,0,5.5,3.8,2,5,3),(-5.4,11,5.5,3.8,2,5,3),(1.6,11,5.5,3.8,2,5,3),(-6,2,4,1,8,3,1),(5,2,4,1,8,3,1),(-5.5,12,-3,4,3,6,0),(1.5,12,-3,4,3,6,0)],
'right_arm':[(-4,-3,-4,7,5,8,1),(-4.5,-2,-3,1,6,6,3),(-3,2,-2.7,4.8,5,5.4,2),(-3.5,7,-3.2,5.5,5,6.4,0),(-4,6,-3.5,6,1.5,7,3),(-3,11,-3,5,2.5,6,1),(-4,8,-1,1.5,3,4,1)],
'left_arm':[(-3,-3,-4,7,5,8,1),(3.5,-2,-3,1,6,6,3),(-1.8,2,-2.7,4.8,5,5.4,2),(-2,7,-3.2,5.5,5,6.4,0),(-2,6,-3.5,6,1.5,7,3),(-2,11,-3,5,2.5,6,1),(2.5,8,-1,1.5,3,4,1)],
'right_leg':[(-2.6,0,-2.8,5.2,6,5.6,2),(-2.8,4,-3.3,5.6,3,1.5,1),(-2.8,7,-3.2,5.6,5,6.2,0),(-3,10,-4,6,3.5,8,1),(-2,7,-3.8,4,3,.8,3)],
'left_leg':[(-2.6,0,-2.8,5.2,6,5.6,2),(-2.8,4,-3.3,5.6,3,1.5,1),(-2.8,7,-3.2,5.6,5,6.2,0),(-3,10,-4,6,3.5,8,1),(-2,7,-3.8,4,3,.8,3)]}
glows={'head':[(-3.7,-5,-5.6,7.4,1.3,.4,4)],'body':[(-1.2,2.4,-4.9,2.4,3.2,.6,4),(-4.6,3,10,2.2,6,.5,4),(2.4,3,10,2.2,6,.5,4),(-5.1,8,-4.4,1.5,.5,.5,4),(3.6,8,-4.4,1.5,.5,.5,4)],'right_arm':[(-3.7,8,-3.6,5.5,.7,.5,4)],'left_arm':[(-1.8,8,-3.6,5.5,.7,.5,4)]}
offsets={'head':(0,0,0),'body':(0,0,0),'right_arm':(-5,2,0),'left_arm':(5,2,0),'right_leg':(-1.9,12,0),'left_leg':(1.9,12,0)}
bands=[0,48,96,144,208]
def builder(boxes):
 s='CubeListBuilder.create()'
 for i,(x,y,z,w,h,d,mat) in enumerate(boxes):s+=f'.texOffs({i%3*40},{bands[mat]}).addBox({x}f,{y}f,{z}f,{w}f,{h}f,{d}f)'
 return s
java='''package com.tnc.tnc.life.routes;
import net.minecraft.client.model.geom.*;
import net.minecraft.client.model.geom.builders.*;
/** Generated by tools/build_skyward_models.py; full articulated suit, not a chest decal. */
public final class RouteMechModel {
 public static final ModelLayerLocation LAYER=new ModelLayerLocation(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("tnc","mana_mech"),"armor");
 public static LayerDefinition layer(){var mesh=net.minecraft.client.model.HumanoidModel.createMesh(CubeDeformation.NONE,0);var root=mesh.getRoot();
'''
geo=[]
for name,boxes in parts.items():
 x,y,z=offsets[name];java+=f' var {name}=root.addOrReplaceChild("{name}",{builder(boxes)},PartPose.offset({x}f,{y}f,{z}f));\n'
 allboxes=boxes
 if name in glows:java+=f' {name}.addOrReplaceChild("glow",{builder(glows[name])},PartPose.ZERO);\n';allboxes=boxes+glows[name]
 cubes=[]
 for i,(a,b,c,w,h,d,mat) in enumerate(allboxes):cubes.append({'origin':[a+x,24-y-b-h,c+z],'size':[w,h,d],'uv':[i%3*40,bands[mat]]})
 geo.append({'name':name,'pivot':[x,24-y,z],'cubes':cubes})
java+=' body.addOrReplaceChild("right_fin",CubeListBuilder.create().texOffs(0,48).addBox(-1,-8,0,2,12,4).texOffs(40,144).addBox(-1.4f,-8.5f,0,2.8f,1,4.5f),PartPose.offsetAndRotation(-6,1,7,-.15f,0,.35f));\n'
java+=' body.addOrReplaceChild("left_fin",CubeListBuilder.create().texOffs(0,48).addBox(-1,-8,0,2,12,4).texOffs(40,144).addBox(-1.4f,-8.5f,0,2.8f,1,4.5f),PartPose.offsetAndRotation(6,1,7,-.15f,0,-.35f));\n'
java+=' head.addOrReplaceChild("crest",CubeListBuilder.create().texOffs(0,144).addBox(-1,-12,-3,2,4,5),PartPose.ZERO);\n'
java+=' return LayerDefinition.create(mesh,256,256);}\n}\n'
(R/'src/main/java/com/tnc/tnc/life/routes/RouteMechModel.java').write_text(java,encoding='utf8')
for side,x,angle in [('right',-6,-20.0535),('left',6,20.0535)]:
 geo.append({'name':side+'_fin','parent':'body','pivot':[x,23,7],'rotation':[8.5944,0,angle],'cubes':[{'origin':[x-1,19,7],'size':[2,12,4],'uv':[0,48]},{'origin':[x-1.4,30.5,7],'size':[2.8,1,4.5],'uv':[40,144]}]})
geo.append({'name':'crest','parent':'head','pivot':[0,24,0],'cubes':[{'origin':[-1,32,-3],'size':[2,4,5],'uv':[0,144]}]})
write(Path('model-source/skyward_mech/skyward_mech.geo.json'),{'format_version':'1.12.0','minecraft:geometry':[{'description':{'identifier':'geometry.tnc.skyward_mech','texture_width':256,'texture_height':256,'visible_bounds_width':3,'visible_bounds_height':3,'visible_bounds_offset':[0,1,0]},'bones':geo}]})
textures={k:'tnc:item/mech_'+k for k in ['metal','ceramic','gold','glow']}
def box(x,y,z,w,h,d,mat,tint=False):
 faces={k:{'texture':'#'+mat,'uv':[0,0,16,16]} for k in ['north','south','east','west','up','down']}
 if tint:
  for f in faces.values():f['tintindex']=0
 return {'from':[x,y,z],'to':[x+w,y+h,z+d],'faces':faces}
body=[box(4,6,2,8,7,11,'metal'),box(3,7,3,2,5,8,'ceramic'),box(11,7,3,2,5,8,'ceramic'),box(5,12,3,6,1.2,10,'ceramic'),box(6,1,9,4,6,4,'metal'),box(5,1,8,6,1.4,6,'gold'),box(5,8,14,6,4,7,'ceramic'),box(4,7,13,8,1.3,6,'gold'),box(7,13,6,2,1,5,'gold'),box(6,6.2,2,4,.6,11,'gold')]
barrels=[];glow=[]
for i in range(6):
 a=i*math.pi/3;x=8+math.cos(a)*2.6;y=9.8+math.sin(a)*2.6
 barrels += [box(x-.7,y-.7,-8,1.4,1.4,11,'metal'),box(x-.9,y-.9,-7,1.8,1.8,1,'gold')]
 glow.append(box(x-.45,y-.45,-8.25,.9,.9,.4,'glow',True))
for name,els in [('body',body),('barrels',barrels),('glow',glow)]:write(Path('src/main/resources/assets/tnc/models/item')/('mech_spellgun_'+name+'.json'),{'parent':'minecraft:block/block','textures':textures,'elements':els,'gui_light':'front'})
display={'thirdperson_righthand':{'rotation':[0,0,0],'translation':[0,1.8,0],'scale':[.72,.72,.72]},'thirdperson_lefthand':{'rotation':[0,0,0],'translation':[0,1.8,0],'scale':[.72,.72,.72]},'firstperson_righthand':{'rotation':[0,8,0],'translation':[2,-1.5,-4],'scale':[.78,.78,.78]},'firstperson_lefthand':{'rotation':[0,-8,0],'translation':[2,-1.5,-4],'scale':[.78,.78,.78]},'gui':{'rotation':[25,225,0],'translation':[0,0,0],'scale':[.62,.62,.62]},'ground':{'rotation':[0,0,0],'translation':[0,3,0],'scale':[.4,.4,.4]},'fixed':{'rotation':[0,180,0],'translation':[0,0,0],'scale':[.6,.6,.6]}}
write(Path('src/main/resources/assets/tnc/models/item/mech_spellgun.json'),{'parent':'builtin/entity','display':display})
write(Path('model-source/skyward_mech/crystal_gun.json'),{'parent':'minecraft:block/block','textures':textures,'elements':body+barrels+glow,'display':display})
print('Generated full suit geometry and six-barrel crystal gun')
